  IF policy->'enabled' IS DISTINCT FROM 'true'::jsonb OR policy->'license_cleared' IS DISTINCT FROM 'true'::jsonb THEN RETURN false;END IF;
  IF coalesce(policy->'mps_resource_policy','null'::jsonb) IS DISTINCT FROM 'null'::jsonb THEN
   IF policy->>'backend' IS DISTINCT FROM 'mps' OR photo.mps_qualification_resources_valid(policy->'mps_resource_policy') IS DISTINCT FROM true OR op NOT IN('face.landmarks','face.detect','face.parse','mask.person') THEN RETURN false;END IF;
  END IF;
  wanted:=jsonb_build_object('Operation',op,'Version','1','Backend',policy->'backend','ModelLockSHA',policy->'model_lock_sha','RuntimeLockSHA',policy->'runtime_lock_sha','DeviceProfileSHA',policy->'device_profile_sha','DatasetSHA',policy->'dataset_sha','IssuerID',policy->'issuer_id','LicenseCleared',true,'MPSResources',coalesce(policy->'mps_resource_policy','null'::jsonb));
  IF coalesce(policy->'mps_resource_policy','null'::jsonb)='null'::jsonb THEN wanted:=wanted-'MPSResources';END IF;
  policy_values:=policy->'required_checks';
  IF jsonb_typeof(policy_values) IS DISTINCT FROM 'array' OR jsonb_array_length(policy_values) NOT BETWEEN 1 AND 256 THEN RETURN false;END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(policy_values) v WHERE jsonb_typeof(v)<>'string' OR length(v#>>'{}') NOT BETWEEN 1 AND 256) OR (SELECT count(DISTINCT v) FROM jsonb_array_elements(policy_values) v)<>jsonb_array_length(policy_values) THEN RETURN false;END IF;
  wanted:=wanted||jsonb_build_object('RequiredChecks',(SELECT jsonb_agg(v ORDER BY v) FROM jsonb_array_elements(policy_values) v));
  FOREACH key IN ARRAY ARRAY['test_fixture_shas','calibration_shas','evidence_shas'] LOOP
   policy_values:=policy->key;
   IF jsonb_typeof(policy_values) IS DISTINCT FROM 'array' OR jsonb_array_length(policy_values)>4096 OR (key<>'calibration_shas' AND jsonb_array_length(policy_values)=0) THEN RETURN false;END IF;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(policy_values) v WHERE jsonb_typeof(v)<>'string' OR (v#>>'{}') !~ '^[0-9a-f]{64}$') OR (SELECT count(DISTINCT v) FROM jsonb_array_elements(policy_values) v)<>jsonb_array_length(policy_values) THEN RETURN false;END IF;
   SELECT coalesce(jsonb_object_agg(v#>>'{}','{}'::jsonb),'{}'::jsonb) INTO shas FROM jsonb_array_elements(policy_values) v;
   wanted:=wanted||jsonb_build_object(CASE key WHEN 'test_fixture_shas' THEN 'TestFixtureSHAs' WHEN 'calibration_shas' THEN 'CalibrationSHAs' ELSE 'EvidenceSHAs' END,shas);
  END LOOP;
  selected:=selected||jsonb_build_object(op,wanted);
 END LOOP;
 IF p_evidence->'source_authority'->'expected' IS DISTINCT FROM selected->'defects.propose' OR p_evidence->'person'->'expected' IS DISTINCT FROM selected->'mask.person' THEN RETURN false;END IF;
 FOR family IN 0..1 LOOP
  entries:=CASE family WHEN 0 THEN p_evidence->'faces' ELSE p_evidence->'parser'->'parsers' END;
  IF jsonb_typeof(entries) IS DISTINCT FROM 'array' OR jsonb_array_length(entries)>64 THEN RETURN false;END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(entries) LOOP
   wanted:=jsonb_build_array(selected->CASE family WHEN 0 THEN 'face.landmarks' ELSE 'face.parse' END,selected->'face.detect');
   IF entry->'expected' IS DISTINCT FROM wanted OR entry->'policies' IS DISTINCT FROM wanted THEN RETURN false;END IF;
  END LOOP;
 END LOOP;
 RETURN true;
EXCEPTION WHEN invalid_parameter_value THEN RETURN false;
END $newbody$;
BEGIN
 PERFORM pg_catalog.set_config('search_path','pg_catalog, pg_temp',true);
 target:=to_regprocedure('photo.semantic_defect_policy_expectations_match(jsonb)');
 IF target IS NULL OR NOT EXISTS(
 SELECT FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner JOIN pg_language l ON l.oid=p.prolang
 WHERE p.oid=target AND r.rolname='photo_fn_owner' AND NOT r.rolcanlogin
 AND p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND NOT p.proretset
 AND p.prokind='f' AND p.provolatile='v' AND p.proparallel='u'
 AND p.pronargs=1 AND p.pronargdefaults=0 AND p.proargtypes[0]='pg_catalog.jsonb'::regtype
 AND p.prorettype='pg_catalog.bool'::regtype AND p.provariadic=0
 AND p.proargdefaults IS NULL AND p.proargnames=ARRAY['p_evidence']::text[] AND p.proallargtypes IS NULL AND p.proargmodes IS NULL
 AND p.proconfig=ARRAY['search_path=pg_catalog, photo']::text[] AND l.lanname='plpgsql'
 AND p.procost=100 AND p.prorows=0 AND p.prosupport=0 AND p.protrftypes IS NULL
 AND p.probin IS NULL AND p.prosqlbody IS NULL
 AND encode(public.digest(convert_to(p.prosrc,'UTF8'),'sha256'),'hex')='c2bfc9613ecf1b7077511d38c18ffced9a5785ad048415dea0800f52393f2d8b'
 AND p.proacl=ARRAY[format('%s=X/%s',r.rolname,r.rolname)::aclitem]
 AND (SELECT count(*) FROM pg_roles scope WHERE scope.rolname=ANY(ARRAY['photo_api','photo_worker','photo_scheduler','photo_maintenance','photo_auth','photo_gateway','photo_portal','photo_publisher']))=8
 AND NOT EXISTS(SELECT FROM pg_roles app WHERE app.rolname=ANY(ARRAY['photo_api','photo_worker','photo_scheduler','photo_maintenance','photo_auth','photo_gateway','photo_portal','photo_publisher']) AND has_function_privilege(app.oid,p.oid,'EXECUTE'))
 ) THEN RAISE EXCEPTION 'EXPECTED_SERIALIZATION_PREDECESSOR_MISMATCH' USING ERRCODE='55000'; END IF;
 SELECT pg_get_functiondef(target),prosrc,to_jsonb(p)-'prosrc' INTO definition,prior,prior_metadata FROM pg_proc p WHERE oid=target;
 IF length(definition)-length(replace(definition,prior,''))<>length(prior) THEN
 RAISE EXCEPTION 'EXPECTED_SERIALIZATION_BODY_AMBIGUOUS' USING ERRCODE='55000';END IF;
 EXECUTE replace(definition,prior,replacement);
 IF NOT EXISTS(SELECT FROM pg_proc WHERE oid=target AND to_jsonb(pg_proc)-'prosrc'=prior_metadata AND encode(public.digest(convert_to(prosrc,'UTF8'),'sha256'),'hex')='275490ace08a797fa5a909b0e278bedc8789603ac8d4c3495dd7be9aeb086a78') THEN
 RAISE EXCEPTION 'EXPECTED_SERIALIZATION_POSTCONDITION' USING ERRCODE='55000';END IF;
 PERFORM pg_catalog.set_config('search_path',caller_search_path,true);
END $rollout$;

